import React from 'react';
import { Provider } from 'react-redux';
import { QueryClientProvider } from 'react-query';
import { ReactQueryDevtools } from 'react-query/devtools';
import { ThemeProvider } from 'styled-components';

import './tailwind.css';
import store from './store';
import queryClient from './utils/queryClient';
import GlobalStyles from './components/GlobalStyles';
import App from './App';

const onRouteChange = (pathname) => {
  // Perform routing meta-refresh styling toggle on header and nav elements
  const isTopLevel = pathname === '/' || pathname.includes('/login');
  const headerClasses = isTopLevel ? 'bg-slate-900/40 backdrop-blur-xl' : '';
  const bodyClasses = isTopLevel ? 'bg-slate-950' : 'bg-slate-900/10';

  document.querySelector('header').classList.toggle('bg-slate-900/40', !isTopLevel);
  document.body.classList.toggle('bg-slate-900/10', !isTopLevel);
  document.body.classList.toggle('min-h-screen', isTopLevel);

  document.documentElement.style.setProperty('--border-slate-300', isTopLevel ? 'hsl(230, 20%, 95%)' : 'transparent');
};

window.addEventListener('hashchange', onRouteChange);
onRouteChange(window.location.pathname);

export default function Root() {
  return (
    <QueryClientProvider client={queryClient}>
      <Provider store={store}>
        <ThemeProvider>
          <GlobalStyles />
          <App onRouteChange={onRouteChange} />
          <ReactQueryDevtools initialIsOpen={false} />
        </ThemeProvider>
      </Provider>
    </QueryClientProvider>
  );
}

